class Solution {
public:
    using u64 = unsigned long long; using u128 = __uint128_t;
    static constexpr u64 MOD = (1ULL << 61) - 1;
    static u64 mm(u64 a, u64 b) { u128 c = (u128)a * b; u64 r = (u64)(c & MOD) + (u64)(c >> 61); return r >= MOD ? r - MOD : r; }
    static u64 pw(u64 b, u64 e) { u64 r = 1; while (e) { if (e & 1) r = mm(r, b); b = mm(b, b); e >>= 1; } return r; }
    vector<int> starts(const string& s, int L, u64 ph, u64 p) {
        int ln = s.size(); vector<u64> h(ln + 1, 0), pb(ln + 1, 1);
        for (int i = 0; i < ln; i++) { h[i + 1] = (mm(h[i], 131) + s[i]) % MOD; pb[i + 1] = mm(pb[i], 131); }
        vector<int> res;
        for (int i = 0; i + L <= ln; i++)
            if ((h[i + L] + MOD - mm(h[i], p)) % MOD == ph) res.push_back(i);
        return res;
    }
    int countCells(vector<vector<char>>& grid, string pattern) {
        int m = grid.size(), n = grid[0].size(), mn = m * n, L = pattern.size();
        string H, V;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) H += grid[i][j];
        for (int j = 0; j < n; j++) for (int i = 0; i < m; i++) V += grid[i][j];
        u64 ph = 0; for (char c : pattern) ph = (mm(ph, 131) + c) % MOD;
        u64 p = pw(131, L);
        vector<int> rh(mn + 1, 0), ch(mn + 1, 0);
        for (int i : starts(H, L, ph, p)) { rh[i]++; rh[i + L]--; }
        for (int i : starts(V, L, ph, p)) { ch[i]++; ch[i + L]--; }
        vector<char> hc(mn, 0), vc(mn, 0);
        int a = 0; for (int t = 0; t < mn; t++) { a += rh[t]; hc[t] = a > 0; }
        a = 0; for (int t = 0; t < mn; t++) { a += ch[t]; vc[t] = a > 0; }
        int ans = 0;
        for (int t = 0; t < mn; t++) if (hc[t] && vc[(t % n) * m + t / n]) ans++;
        return ans;
    }
};

