class Solution {
    static final long M1 = 1000000007L, M2 = 998244353L, B = 131;
    List<Integer> starts(String s, int L, long p1, long p2, long q1, long q2) {
        int ln = s.length();
        long[] h1 = new long[ln + 1], h2 = new long[ln + 1], a1 = new long[ln + 1], a2 = new long[ln + 1];
        for (int i = 0; i < ln; i++) {
            h1[i + 1] = (h1[i] * B + s.charAt(i)) % M1; h2[i + 1] = (h2[i] * B + s.charAt(i)) % M2;
            a1[i + 1] = a1[i] * B % M1; a2[i + 1] = a2[i] * B % M2;
        }
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i + L <= ln; i++) {
            long c1 = ((h1[i + L] - h1[i] * q1 % M1) % M1 + M1) % M1;
            long c2 = ((h2[i + L] - h2[i] * q2 % M2) % M2 + M2) % M2;
            if (c1 == p1 && c2 == p2) res.add(i);
        }
        return res;
    }
    public int countCells(char[][] grid, String pattern) {
        int m = grid.length, n = grid[0].length, mn = m * n, L = pattern.length();
        StringBuilder H = new StringBuilder(), V = new StringBuilder();
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) H.append(grid[i][j]);
        for (int j = 0; j < n; j++) for (int i = 0; i < m; i++) V.append(grid[i][j]);
        long p1 = 0, p2 = 0; for (char c : pattern.toCharArray()) { p1 = (p1 * B + c) % M1; p2 = (p2 * B + c) % M2; }
        long q1 = 1, q2 = 1; for (int i = 0; i < L; i++) { q1 = q1 * B % M1; q2 = q2 * B % M2; }
        int[] rh = new int[mn + 1], ch = new int[mn + 1];
        for (int i : starts(H.toString(), L, p1, p2, q1, q2)) { rh[i]++; rh[i + L]--; }
        for (int i : starts(V.toString(), L, p1, p2, q1, q2)) { ch[i]++; ch[i + L]--; }
        boolean[] hc = new boolean[mn], vc = new boolean[mn];
        int a = 0; for (int t = 0; t < mn; t++) { a += rh[t]; hc[t] = a > 0; }
        a = 0; for (int t = 0; t < mn; t++) { a += ch[t]; vc[t] = a > 0; }
        int ans = 0;
        for (int t = 0; t < mn; t++) if (hc[t] && vc[(t % n) * m + t / n]) ans++;
        return ans;
    }
}

